import{_ as n,o as e,c as s,aj as r}from"./chunks/framework.BdtAaXf2.js";const t="/assets/image-20260610001702465.SJW8oNcO.png",o="/assets/image-20260609234550956.DeSChGkx.png",i="/assets/image-20260609234637582.CKhyexRx.png",p="/assets/image-20260609234809632.B5ukptpt.png",g="/assets/image-20260609235826004.CAg4NrxZ.png",l="/assets/image-20260610000316355.BBCsv5ZB.png",d="/assets/image-20260610000354320.Ccy8D9sx.png",m="/assets/image-20260610000657889.DCqfXUiX.png",c="/assets/image-20260610000758838.BGB5lt3H.png",_="/assets/image-20260610001143683.GynjM0X-.png",h="/assets/image-20260610001153378.TGCCkTf8.png",x=JSON.parse('{"title":"24小时员工——腾讯有Marvis，阿里也出了个QoderWake","description":"","frontmatter":{},"headers":[],"relativePath":"AI人工智能/腾讯有Marvis，阿里也出了个QoderWake/腾讯有Marvis，阿里也出了个QoderWake.md","filePath":"AI人工智能/腾讯有Marvis，阿里也出了个QoderWake/腾讯有Marvis，阿里也出了个QoderWake.md","lastUpdated":1781048308000,"__rawMarkdown":"# 24小时员工——腾讯有Marvis，阿里也出了个QoderWake\\n\\n> https://qoder.com/qoderwake\\n\\n![](assets/image-20260610001702465.png)\\n\\n## 前言\\n\\n众所周知，前阵子腾讯出了个Marvis-马维斯，号称是你24小时在线的员工，因为它可视化的界面，和萌萌哒的设计，俘获了不少办公人士的心。\\n\\n\\n\\n![](assets/image-20260609234550956.png)\\n\\n---\\n\\n![](assets/image-20260609234637582.png)\\n\\n---\\n\\n## QoderWake\\n\\n今天看了下Qoder的海外站，发现一个对标的产品已赫然在列——**QoderWake**\\n\\n![](assets/image-20260609234809632.png)\\n\\n图片中显示的\\n\\n> Always awake —— 永远清醒\\n>\\n> Always working —— 始终在工作\\n\\n这个提示语和腾讯的Marvis——24小时工作——对立起来就很明显了。\\n\\n---\\n\\n不知道大家有没有一种同情赛博员工的冲动，或者有没有一点联想到自己加班状态的画面。\\n\\n目前它预置 **6+个岗位、100+技能**。\\n\\n阿里的办公能力相信有目共睹，其中Qoder系列**万少**也一直深度使用，除了贵，其他在国产环境内挑不出毛病。\\n\\n目前只支持**MacOS** 和  **Linux**系统\\n\\n\\n\\n## 角色\\n\\n目前提供了 后端工程师、前端工程师、测试工程师和产品经理、数据分析师、内容运营和自定义角色。\\n\\n可以充分看到这个明显就是针对开发、运营团队设立的角色了。\\n\\n![](assets/image-20260609235826004.png)\\n\\n## 启动\\n\\n![](assets/image-20260610000316355.png)\\n\\n你可以根据任务需求，选择一个角色，比如前端开发工程师，可以修改名称、头像和默认的简介。\\n\\n![](assets/image-20260610000354320.png)\\n\\n---\\n\\n然后可以选择**直接对话**或者**创建自动任务**\\n\\n## 对话\\n\\n开始对话时，如果是需要编辑文件，需要先选择一个工作目录。\\n\\n![](assets/image-20260610000657889.png)\\n\\n---\\n\\n然后可以选择 **文件夹** 或者 **项目**\\n\\n![](assets/image-20260610000758838.png)\\n\\n两者的区别是：\\n\\n1. 文件夹：直接选择一个文件夹。\\n2. 项目：选择文件夹后还会帮你进行这个文件夹基本的初始化，比如该目录具体是做什么工程的。\\n\\n---\\n\\n选择完毕后，就可以直接对话了。\\n\\n\\n\\n## 自动任务\\n\\n自动任务，提供了两种触发方式：\\n\\n1. 第一种很好理解，就是定时任务。\\n2. 第二种可能非程序员不好理解，就是Git仓库事件触发。（git仓库是一个远程托管资料的地址，当有文件新增等事件时，可以发起通知）。\\n\\n还可以根据情况选择 定期触发或者是一次性触发。\\n\\n其中的高级设置还提供了运行次数和截止日期，看到运行次数无限制和截止日期——永无止境，我一阵心疼这些赛博牛马。\\n\\n![](assets/image-20260610001143683.png)\\n\\n---\\n\\n![](assets/image-20260610001153378.png)\\n\\n\\n\\n## 总结\\n\\n\\n\\n还没有体验的小伙伴可以去试试，尽早掌握一些AI工具，可能会让你更好的提效。"}'),k={name:"AI人工智能/腾讯有Marvis，阿里也出了个QoderWake/腾讯有Marvis，阿里也出了个QoderWake.md"};function q(u,a,b,f,v,Q){return e(),s("div",null,[...a[0]||(a[0]=[r("",50)])])}const w=n(k,[["render",q]]);export{x as __pageData,w as default};
